// Help → Open-source licences (PK1): one read-only window showing THIRD_PARTY_NOTICES.txt, the
// notices generated by scripts/third-party-notices.mjs. Plain text in a sandboxed window without
// preload or project session; menu items it receives go to a project window (src/main/index.ts).
// Doc: docs/conventions/packaging.md#third-party-notices
import { BrowserWindow } from 'electron'
import { existsSync } from 'node:fs'
import { join } from 'node:path'

export const NOTICES_FILE = 'THIRD_PARTY_NOTICES.txt'

/** Next to the asar when packaged; in development, out/ after `npm run notices` or `package`. */
export function noticesPath(packaged: boolean, resourcesPath: string, appPath: string): string {
  return packaged ? join(resourcesPath, NOTICES_FILE) : join(appPath, 'out', NOTICES_FILE)
}

/** Shown in development when the notices were not generated. */
export const NOT_GENERATED =
  'The third-party notices are generated when the app is packaged.\n\n' +
  'In development, run `npm run build && npm run notices` and open this window again.'

/** Monospace text that follows the light / dark theme (Chromium shows a .txt as one <pre>). */
const TEXT_CSS = `:root { color-scheme: light dark; }
body { margin: 0; padding: 16px 20px; }
pre { font: 12px/1.5 ui-monospace, 'SF Mono', Menlo, Consolas, monospace; }`

export interface LicencesWindow {
  /** Opens the window, or brings it to the front (never shown in hidden test runs). */
  open(): void
  isLicences(win: BrowserWindow | null | undefined): boolean
}

export function createLicencesWindow(opts: {
  readonly path: string
  readonly hidden: boolean
}): LicencesWindow {
  let win: BrowserWindow | undefined
  const live = () => (win !== undefined && !win.isDestroyed() ? win : undefined)
  return {
    open() {
      const existing = live()
      if (existing !== undefined) {
        if (!opts.hidden) existing.focus()
        return
      }
      const created = new BrowserWindow({
        width: 760,
        height: 640,
        minWidth: 480,
        minHeight: 320,
        show: false,
        title: 'Open-source licences',
        webPreferences: { sandbox: true, contextIsolation: true, nodeIntegration: false },
      })
      win = created
      // the text has no links to follow; nothing navigates away or opens windows
      created.webContents.on('will-navigate', (event) => event.preventDefault())
      created.webContents.setWindowOpenHandler(() => ({ action: 'deny' }))
      created.on('page-title-updated', (event) => event.preventDefault())
      created.webContents.on('did-finish-load', () => void created.webContents.insertCSS(TEXT_CSS))
      if (!opts.hidden) created.once('ready-to-show', () => created.show())
      if (existsSync(opts.path)) void created.loadFile(opts.path)
      else
        void created.loadURL(`data:text/plain;charset=utf-8,${encodeURIComponent(NOT_GENERATED)}`)
    },
    isLicences: (w) => w !== null && w !== undefined && w === live(),
  }
}
